import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const root = new Group();
  const inner = new Group();
  root.add(inner);

  // Label card dimensions (atlas aspect 512:320 = 1.6:1)
  const W = 1.6, H = 1.0;

  // --- Backdrop: engineered vertical gradient (surface -> ink) ---
  const bdMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  bdMat.colorNode = mix(vec3(surface), vec3(ink), uv().y);
  const backdrop = new Mesh(new PlaneGeometry(W, H), bdMat);
  backdrop.position.z = -0.02;
  inner.add(backdrop);

  // --- Ceramic-grain texture overlay (subtle) ---
  const grainMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  grainMat.colorNode = mix(vec3(surface), vec3(ink), uv().y);
  const grain = new Mesh(new PlaneGeometry(W, H), grainMat);
  grain.position.z = -0.01;
  inner.add(grain);

  // --- Accent signal bar (<=10% of frame, left edge) ---
  const accMat = new MeshBasicNodeMaterial({ transparent: true });
  accMat.colorNode = vec3(accent);
  const accBar = new Mesh(new PlaneGeometry(0.04, H * 0.72), accMat);
  accBar.position.set(-W / 2 + 0.05, 0, 0.001);
  inner.add(accBar);

  // --- Text content ---
  const textMeshes = [];
  for (const item of items) {
    const fs = item.typography?.fontSize ?? 39;
    const role = item.role ?? 'headline';
    const txt = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize: fs,
      color: '#' + paper.getHexString(),
      align: 'center',
      maxWidthPx: 150,
      letterSpacingPx: role === 'headline' ? 1.5 : 0.5,
    });
    txt.scale.setScalar(0.01);
    txt.position.set(0.05, 0, 0.01);
    inner.add(txt);
    textMeshes.push(txt);
  }

  // --- Async texture load (grain) ---
  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      const grad = mix(vec3(surface), vec3(ink), uv().y);
      grainMat.colorNode = mix(grad, texture(tex, uv()), float(0.1));
      grainMat.needsUpdate = true;
      loadedTex = tex;
    });
  }

  // --- Entrance motion (rise-in + weighted-settle) ---
  inner.position.y = 0.2;
  inner.scale.set(0.97, 0.97, 1);
  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.6, ease: 'power3.out' });
  tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power3.out' }, 0);
  tl.to(inner.scale, { x: 1.04, y: 1.04, z: 1, duration: 0.3, ease: 'power2.out' }, 0.6);
  tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' }, 0.9);

  // --- Event handlers (none specified; static composition) ---
  root.userData.handlers = {};

  // --- Cleanup ---
  root.userData.cleanup = () => {
    tl.kill();
    bdMat.dispose();
    grainMat.dispose();
    accMat.dispose();
    backdrop.geometry.dispose();
    grain.geometry.dispose();
    accBar.geometry.dispose();
    if (loadedTex) loadedTex.dispose?.();
    for (const t of textMeshes) {
      t.traverse((o) => {
        if (o.geometry) o.geometry.dispose?.();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
          else o.material.dispose?.();
        }
      });
    }
  };

  return root;
}
